package com.maikal.courses;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import org.json.*;import java.util.*;
public class ReminderReceiver extends BroadcastReceiver {
 static final String CHANNEL="learning_reminders";static void channel(Context c){NotificationManager n=c.getSystemService(NotificationManager.class);NotificationChannel ch=new NotificationChannel(CHANNEL,"Learning reminders",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Your chosen learning reminder times");n.createNotificationChannel(ch);}
 static PendingIntent pending(Context c,int slot){Intent i=new Intent(c,ReminderReceiver.class).setAction("com.maikal.courses.REMIND").putExtra("slot",slot);return PendingIntent.getBroadcast(c,400+slot,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c){channel(c);AlarmManager a=c.getSystemService(AlarmManager.class);for(int i=0;i<4;i++)a.cancel(pending(c,i));JSONObject r=AppState.state(c).optJSONObject("reminders");if(r==null||!r.optBoolean("enabled")||!c.getSystemService(NotificationManager.class).areNotificationsEnabled()||AppState.pending(AppState.state(c)).isEmpty())return;JSONArray times=r.optJSONArray("times");if(times==null||times.length()<3||times.length()>4)return;for(int i=0;i<times.length();i++){String time=times.optString(i);if(!time.matches("([01][0-9]|2[0-3]):[0-5][0-9]"))continue;Calendar next=Calendar.getInstance();next.set(Calendar.HOUR_OF_DAY,Integer.parseInt(time.substring(0,2)));next.set(Calendar.MINUTE,Integer.parseInt(time.substring(3)));next.set(Calendar.SECOND,0);next.set(Calendar.MILLISECOND,0);if(next.getTimeInMillis()<=System.currentTimeMillis()||AppState.today(AppState.state(c))>=AppState.goal(AppState.state(c)))next.add(Calendar.DAY_OF_YEAR,1);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next.getTimeInMillis(),pending(c,i));}}
 @Override public void onReceive(Context c,Intent intent){schedule(c);StreakWidget.refresh(c);if(!"com.maikal.courses.REMIND".equals(intent.getAction()))return;JSONObject s=AppState.state(c);JSONObject r=s.optJSONObject("reminders");if(r==null||!r.optBoolean("enabled")||AppState.today(s)>=AppState.goal(s))return;String id=AppState.pending(s);if(id.isEmpty())return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;NotificationManager manager=c.getSystemService(NotificationManager.class);if(!manager.areNotificationsEnabled())return;Notification notification=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_logo).setContentTitle("Miko saved your place").setContentText(AppState.title(id)+" is waiting. A tiny session keeps your streak going.").setStyle(new Notification.BigTextStyle().bigText("You started "+AppState.title(id)+". Continue your adventure with one small session and keep your learning streak growing.")).setAutoCancel(true).setContentIntent(AppState.open(c,id,99)).build();manager.notify(900,notification);}
}
